 "Aandelenuitkering of omzetting: de oorspronkelijke aandelen en over te dragen kostprijs moeten worden gecontroleerd. Deze regel blijft apart bewaard; boek dit niet als dividend of gewone aankoop.": {
  "nl": "Aandelenuitkering of omzetting: de oorspronkelijke aandelen en over te dragen kostprijs moeten worden gecontroleerd. Deze regel blijft apart bewaard; boek dit niet als dividend of gewone aankoop.",
  "en": "Share distribution or conversion: verify original shares and transferred cost basis. This row is kept separately; do not record it as a dividend or normal purchase.",
  "es": "Distribución o conversión de acciones: verifica las acciones originales y el coste transferido. La fila se conserva aparte; no la registres como dividendo o compra normal."
 },
 "Aantal of prijs ontbreekt. Bij een fusie of intrekking kan de broker een nulprijs rapporteren; controleer de bijbehorende aandelenuitkering en kostprijs bij Te beoordelen.": {
  "nl": "Aantal of prijs ontbreekt. Bij een fusie of intrekking kan de broker een nulprijs rapporteren; controleer de bijbehorende aandelenuitkering en kostprijs bij Te beoordelen.",
  "en": "Quantity or price is missing. A broker may report a zero price for a merger or cancellation; check the related share distribution and cost under To review.",
  "es": "Falta la cantidad o el precio. En una fusión o cancelación el bróker puede indicar precio cero; revisa la distribución de acciones y su coste en Pendiente de revisión."
 },
